/**
 * @name XML External Entity (XXE) vulnerability in lxml
 * @description Detects XML parsing with external entity expansion enabled, which can lead to file disclosure or SSRF
 * @kind path-problem
 * @problem.severity error
 * @id py/xxe-lxml
 * @tags security
 *        external/cwe/cwe-611
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module XXEConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Look for XML parsing calls with potentially unsafe parameters
    exists(DataFlow::CallCfgNode call |
      sink = call.getArg(0) and
      (
        call = API::moduleImport("lxml.etree").getMember(["parse", "fromstring", "XML", "HTML"]).getACall() or
        call = API::moduleImport("lxml.html").getMember(["parse", "fromstring", "HTML"]).getACall() or
        call = API::moduleImport("xml.etree.ElementTree").getMember(["parse", "fromstring"]).getACall()
      )
    )
  }
}

module XXEFlow = TaintTracking::Global<XXEConfig>;
import XXEFlow::PathGraph

from XXEFlow::PathNode source, XXEFlow::PathNode sink
where XXEFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "XML parsing with user input may be vulnerable to XXE: $@.", source.getNode(), "user input"

/**
 * @name XPath injection in lxml
 * @description User input flowing into XPath expressions can lead to XPath injection
 * @kind path-problem
 * @problem.severity high
 * @id py/xpath-injection-lxml
 * @tags security
 *        external/cwe/cwe-643
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module XPathInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Look for xpath() method calls on lxml elements
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("lxml").getMember("etree").getMember("Element").getMember("xpath").getACall() or
      call = API::moduleImport("lxml").getMember("html").getMember("HtmlElement").getMember("xpath").getACall()
    |
      sink = call.getArg(0)  // First argument is the XPath expression
    )
  }
}

module XPathInjectionFlow = TaintTracking::Global<XPathInjectionConfig>;
import XPathInjectionFlow::PathGraph

from XPathInjectionFlow::PathNode source, XPathInjectionFlow::PathNode sink
where XPathInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "XPath injection from $@.", source.getNode(), "user input"

